// CR-12 E4: Suchanfrage pruefen (nur lesen). Erwartet JSON { q, person, kategorie, von, bis }.
const b = ($input.first().json || {}).body || {};
const s = function (v, max) { return typeof v === 'string' ? v.trim().slice(0, max) : ''; };
const q = s(b.q, 200);
const person = s(b.person, 30);
const kat = s(b.kategorie, 60);
const von = s(b.von, 10);
const bis = s(b.bis, 10);
const datum = function (v) { if (!v) return ''; if (!/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(v)) return null; const t = new Date(v + 'T12:00:00Z'); return (!isNaN(t.getTime()) && t.toISOString().slice(0, 10) === v) ? v : null; };
let fehler = null;
if (q.replace(/\s+/g, '').length < 2) fehler = 'Bitte mindestens 2 Zeichen eingeben.';
else if (person && !/^[a-z][a-z_]{1,29}$/.test(person)) fehler = 'Ungültige Person.';
else if (kat && !/^[a-z][a-z0-9_]{1,59}$/.test(kat)) fehler = 'Ungültige Kategorie.';
else if (datum(von) === null || datum(bis) === null) fehler = 'Ungültiges Datum.';
if (fehler) return [{ json: { ok: false, fehler: fehler } }];
return [{ json: { ok: true, p64: Buffer.from(JSON.stringify({ q: q, person: person, kategorie: kat, von: von, bis: bis }), 'utf8').toString('base64') } }];

// CR-12 E4: Trefferliste fuer die Weboberflaeche (Ausschnitt hoechstens 220 Zeichen, kein Volltext).
const p = $('Suche pruefen').first().json;
if (!p.ok) return [{ json: { antwort: { ok: false, fehler: p.fehler } } }];
const rows = $input.all().map(function (x) { return x.json || {}; });
if (rows.some(function (r) { return r.error; })) return [{ json: { antwort: { ok: false, fehler: 'Die Suche ist gerade nicht möglich. Bitte später erneut versuchen.' } } }];
const treffer = rows.filter(function (r) { return r && r.document_id; }).map(function (r) {
  return { id: r.document_id, person: r.person_key || null, status: r.status, kategorie: r.kategorie_key || null, datum: r.dokumentdatum || null, titel: r.titel || null,
    absender: r.absender || null, ablage: r.ablage || null, link: (typeof r.link === 'string' && /^https:\/\/drive\.google\.com\//.test(r.link)) ? r.link : null,
    ausschnitt: r.ausschnitt || null, volltext: r.quelle_volltext === true };
});
return [{ json: { antwort: { ok: true, anzahl: treffer.length, treffer: treffer } } }];
